package org.sleepwell.app;

import android.content.*;
import android.net.Uri;
import android.os.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Retained foreground operation. The detector is created, used and closed on one worker. */
final class RecordedRecognitionJob implements AutoCloseable {
    enum Phase {IDLE,CHOOSING,READING,READY,ANALYZING,RESULT,ERROR,CLOSED}
    interface Observer {void changed();}
    private static final Set<RecordedRecognitionJob> JOBS=ConcurrentHashMap.newKeySet();
    private static final Semaphore DETECTOR=new Semaphore(1);
    private static final ScheduledExecutorService DEADLINES=Executors.newSingleThreadScheduledExecutor();
    final Context app;final Records.Factory factory;final long record,clip,event,updated;
    static final class ClipChoice {final long id,time,duration;final boolean pending;ClipChoice(JSONObject value){id=value.optLong("id");time=value.optLong("time");duration=value.optLong("duration_ms");pending=value.optInt("pending")!=0;}}
    List<ClipChoice> clips=List.of();boolean moreClips;private long pageTime=Long.MIN_VALUE,pageId;private final List<long[]> previousPages=new ArrayList<>();
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private final Object authority=new Object();
    private Observer observer;private volatile boolean closed,invalidated,cancelled;private volatile int generation;private volatile InputStream stream;private volatile CancellationSignal signal;
    Phase phase=Phase.IDLE;String message="",progress="",notice="";volatile RecordedRecognitionInput input;volatile RecordedRecognitionStore.Entry result;List<RecordedRecognitionStore.Entry> saved=List.of();long revision;
    RecordedRecognitionJob(Context c,Records.Factory factory,long record,long clip,long event,long updated){app=c.getApplicationContext();this.factory=factory;this.record=record;this.clip=clip;this.event=event;this.updated=updated;JOBS.add(this);refresh();}
    void observe(Observer value){observer=value;notifyNow();}void detach(Observer value){if(observer==value)observer=null;}
    private void notifyNow(){if(Looper.myLooper()!=Looper.getMainLooper()){main.post(this::notifyNow);return;}if(observer!=null&&!closed)observer.changed();}
    private boolean live(int token){return !closed&&!invalidated&&!cancelled&&generation==token;}
    private void publish(int token,Runnable action){main.post(()->{if(live(token)){action.run();notifyNow();}});}
    boolean busy(){return phase==Phase.READING||phase==Phase.ANALYZING||phase==Phase.CHOOSING;}
    private boolean occupied(){return Prefs.flag(app,"ringing")||TrackingService.running;}
    private void allowed()throws IOException {if(occupied())throw new IOException("End tracking or the active alarm before analyzing recordings.");}
    private void failure(int token,Throwable error){String text=error.getMessage();String detail=error instanceof LinkageError?"The bundled analyzer is unavailable on this device. Audio and saved labels were not changed.":text==null?"Analysis could not finish. Select and review the audio again.":text.length()>240?"This audio could not be analyzed. Check the format or try again with a shorter recording.":text;publish(token,()->{phase=Phase.ERROR;message=detail;progress="";});}
    void refresh(){if(closed||busy())return;int token=++generation;cancelled=false;worker.execute(()->{try(RecordedRecognitionStore store=new RecordedRecognitionStore(app)){List<RecordedRecognitionStore.Entry> entries=store.entries();long current=store.revision();List<ClipChoice> choices=record>0&&clip<=0?choices(pageTime,pageId):List.of();publish(token,()->{saved=entries;revision=current;if(record>0&&clip<=0){moreClips=choices.size()>20;clips=List.copyOf(choices.subList(0,Math.min(20,choices.size())));}});}catch(Exception error){failure(token,error);}});}
    private List<ClipChoice> choices(long time,long id)throws Exception {try(Store store=factory.open(app)){RecordEntry night=Records.get(store,record);if(updated>=0&&night.updated!=updated)throw new IOException("The night changed. Reopen sound events.");List<ClipChoice> out=new ArrayList<>();for(JSONObject row:store.rows("SELECT c.id,c.time,c.duration_ms,EXISTS(SELECT 1 FROM pending_clip_deletes p WHERE p.clip=c.id) AS pending FROM clips c JOIN sessions s ON s.id=c.session WHERE s.end IS NOT NULL AND c.session=? AND (c.time>CAST(? AS INTEGER) OR (c.time=CAST(? AS INTEGER) AND c.id>CAST(? AS INTEGER))) ORDER BY c.time,c.id LIMIT 21",""+record,""+time,""+time,""+id))out.add(new ClipChoice(row));return out;}}
    boolean previousClips(){return !previousPages.isEmpty();}
    void pageClips(boolean next){if(closed||invalidated||busy())return;long time,id;if(next){if(!moreClips||clips.isEmpty())return;ClipChoice last=clips.get(clips.size()-1);time=last.time;id=last.id;}else{if(previousPages.isEmpty())return;long[] previous=previousPages.get(previousPages.size()-1);time=previous[0];id=previous[1];}int token=++generation;cancelled=false;phase=Phase.READING;progress="Loading saved recordings…";notifyNow();worker.execute(()->{try{List<ClipChoice> choices=choices(time,id);publish(token,()->{if(next)previousPages.add(new long[]{pageTime,pageId});else previousPages.remove(previousPages.size()-1);pageTime=time;pageId=id;moreClips=choices.size()>20;clips=List.copyOf(choices.subList(0,Math.min(20,choices.size())));phase=Phase.IDLE;progress="";});}catch(Exception error){failure(token,error);}});}
    boolean choosing(){if(closed||invalidated||busy())return false;if(occupied()){message="End tracking or the active alarm first.";notifyNow();return false;}phase=Phase.CHOOSING;message="";notifyNow();return true;}
    void choiceCancelled(String error){if(phase!=Phase.CHOOSING)return;phase=input==null?Phase.IDLE:Phase.READY;message=error==null?"No file selected.":error;notifyNow();}
    void selected(Uri uri){if(closed||phase!=Phase.CHOOSING)return;if(uri==null||!"content".equals(uri.getScheme())){choiceCancelled("Choose one document from the file picker.");return;}prepare(uri,0);}
    void retained(){retained(clip);}
    void retained(long chosenClip){if(record<=0||chosenClip<=0||busy())return;prepare(null,chosenClip);}
    private void prepare(Uri uri,long retainedClip){
        if(closed||invalidated)return;if(occupied()){phase=Phase.ERROR;message="End tracking or the active alarm first.";notifyNow();return;}int token=++generation;cancelled=false;phase=Phase.READING;message="";progress="Preparing a private audio copy…";result=null;RecordedRecognitionInput prior=input;input=null;notifyNow();
        worker.execute(()->{if(prior!=null)prior.erase();RecordedRecognitionInput copy=null;CancellationSignal request=new CancellationSignal();signal=request;ScheduledFuture<?> timeout=DEADLINES.schedule(()->{if(live(token)){request.cancel();closeStream();}},30,TimeUnit.SECONDS);long deadline=SystemClock.elapsedRealtime()+30000;
            try{allowed();try(RecordedRecognitionStore store=new RecordedRecognitionStore(app)){long expected=store.revision();
                if(retainedClip>0)copy=RecordedRecognitionInput.retained(app,factory,record,retainedClip,event,updated,null,()->live(token)&&SystemClock.elapsedRealtime()<deadline);
                else{android.os.ParcelFileDescriptor descriptor=app.getContentResolver().openFileDescriptor(uri,"r",request);if(descriptor==null)throw new IOException("This document could not be opened.");byte[] bytes;try(InputStream opened=new android.os.ParcelFileDescriptor.AutoCloseInputStream(descriptor)){stream=opened;bytes=RecordedRecognitionInput.copy(opened,()->live(token)&&SystemClock.elapsedRealtime()<deadline);}finally{stream=null;}
                    try{copy=RecordedRecognitionInput.wav(bytes,new JSONObject().put("kind","selected_wav").put("provenance","Explicitly selected WAV; original source unverified"),0,Long.MAX_VALUE,()->live(token)&&SystemClock.elapsedRealtime()<deadline);}finally{Arrays.fill(bytes,(byte)0);}}
                allowed();RecordedRecognitionInput completed=copy;if(!live(token)){completed.erase();return;}main.post(()->{if(!live(token)){completed.erase();return;}input=completed;revision=expected;phase=Phase.READY;message="Review this copy, then explicitly start analysis.";progress="";notifyNow();});copy=null;
            }}catch(Exception error){failure(token,error);}finally{if(copy!=null)copy.erase();timeout.cancel(false);if(signal==request)signal=null;closeStream();}
        });
    }
    void analyze(){if(closed||phase!=Phase.READY||input==null)return;RecordedRecognitionInput reviewed=input;int token=++generation;cancelled=false;long expected=revision;phase=Phase.ANALYZING;message="";progress="Loading the bundled offline model…";notifyNow();
        worker.execute(()->{boolean acquired=false;try{allowed();if(!live(token))return;if(!DETECTOR.tryAcquire())throw new IOException("Another recorded-audio analysis is finishing. Try again shortly.");acquired=true;long deadline=SystemClock.elapsedRealtime()+180000;
            if(reviewed.source.optString("kind").equals("saved_clip"))verify(reviewed,token,null);
            RecordedSoundAnalyzer.Result analyzed;try(RecordedSoundAnalyzer analyzer=new RecordedSoundAnalyzer(app)){analyzed=analyzer.analyze(reviewed.pcm,()->!live(token)||occupied()||SystemClock.elapsedRealtime()>deadline,(done,total)->publish(token,()->progress="Analyzing window "+done+" of "+total+"…"));}
            RecordedRecognitionInput.check(()->live(token)&&SystemClock.elapsedRealtime()<=deadline);allowed();JSONObject json=analyzed.json();JSONObject provenance=reviewed.provenance();final RecordedRecognitionStore.Entry[] stored=new RecordedRecognitionStore.Entry[1];
            if(reviewed.source.optString("kind").equals("saved_clip"))verify(reviewed,token,fresh->stored[0]=commit(token,expected,provenance,json));
            else stored[0]=commit(token,expected,provenance,json);
            List<RecordedRecognitionStore.Entry> entries;try(RecordedRecognitionStore store=new RecordedRecognitionStore(app)){entries=store.entries();}
            publish(token,()->{result=stored[0];saved=entries;phase=Phase.RESULT;progress="";message="Saved on this phone. These are experimental estimates, not confirmed events.";input=null;});
        }catch(Exception|LinkageError error){failure(token,error);}finally{if(acquired)DETECTOR.release();reviewed.erase();main.post(()->{if(input==reviewed)input=null;});}});
    }
    private RecordedRecognitionStore.Entry commit(int token,long expected,JSONObject source,JSONObject result)throws Exception {synchronized(authority){RecordedRecognitionInput.check(()->live(token));allowed();try(RecordedRecognitionStore store=new RecordedRecognitionStore(app)){return store.save(expected,source,result);}}}
    private void verify(RecordedRecognitionInput reviewed,int token,RecordedRecognitionInput.Validated action)throws Exception {JSONObject s=reviewed.provenance();RecordedRecognitionInput checked=RecordedRecognitionInput.retained(app,factory,s.getLong("record"),s.getLong("clip"),s.getLong("event"),s.getLong("updated"),s,()->live(token)&&!occupied(),action);checked.erase();}
    void open(RecordedRecognitionStore.Entry selected){if(closed||busy())return;int token=++generation;cancelled=false;phase=Phase.READING;progress="Checking saved result provenance…";message="";result=null;notifyNow();worker.execute(()->{try{allowed();if(selected.source.optString("kind").equals("saved_clip")){JSONObject s=selected.source;RecordedRecognitionInput checked=RecordedRecognitionInput.retained(app,factory,s.getLong("record"),s.getLong("clip"),s.getLong("event"),s.getLong("updated"),s,()->live(token));checked.erase();}try(RecordedRecognitionStore store=new RecordedRecognitionStore(app)){boolean present=false;for(RecordedRecognitionStore.Entry e:store.entries())if(e.id.equals(selected.id))present=true;if(!present)throw new IOException("This saved analysis was deleted.");}publish(token,()->{result=selected;phase=Phase.RESULT;progress="";message="";});}catch(Exception error){failure(token,error);}});}
    void delete(RecordedRecognitionStore.Entry selected){if(closed||busy())return;int token=++generation;cancelled=false;worker.execute(()->{try(RecordedRecognitionStore store=new RecordedRecognitionStore(app)){store.delete(selected.id);List<RecordedRecognitionStore.Entry> entries=store.entries();publish(token,()->{saved=entries;if(result!=null&&result.id.equals(selected.id))result=null;phase=Phase.IDLE;message="Saved analysis deleted. Original audio is unchanged.";});}catch(Exception error){failure(token,error);}});}
    void clearSaved(){if(closed||busy())return;worker.execute(()->{try{RecordedRecognitionStore.clear(app);}catch(Exception error){main.post(()->{if(!closed){message="Saved analyses could not be cleared. Try again.";notifyNow();}});}});}
    void notice(String name){if(closed||invalidated||busy()||!List.of("NOTICE.txt","PANN-WEIGHTS-CC-BY-4.0.txt","PANN-CODE-MIT.txt","EFFICIENTAT-MIT.txt","ONNX-RUNTIME-MIT.txt").contains(name))return;Phase previous=phase;int token=++generation;cancelled=false;phase=Phase.READING;progress="Loading bundled model notices…";notifyNow();worker.execute(()->{try(InputStream in=app.getAssets().open("recorded-sound/"+name)){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];for(int n;(n=in.read(buffer))!=-1;){RecordedRecognitionInput.check(()->live(token));if(bytes.size()+n>131072)throw new IOException("Bundled notice exceeds its supported size.");bytes.write(buffer,0,n);}String text=new String(bytes.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);publish(token,()->{notice=name+"\n\n"+text;phase=previous;progress="";});}catch(Exception error){failure(token,error);}});}
    void hideNotice(){notice="";notifyNow();}
    void cancel(){if(closed)return;synchronized(authority){cancelled=true;++generation;}CancellationSignal current=signal;if(current!=null)current.cancel();closeStream();RecordedRecognitionInput prior=input;input=null;try{worker.execute(()->{if(prior!=null)prior.erase();});}catch(RejectedExecutionException ended){if(prior!=null)prior.erase();}phase=Phase.IDLE;progress="";message="Cancelled. A running native step may finish before its private copy is discarded.";notifyNow();}
    private void closeStream(){InputStream current=stream;stream=null;if(current!=null)try{current.close();}catch(IOException ignored){}}
    static void invalidateAll(){for(RecordedRecognitionJob job:JOBS){job.invalidated=true;job.cancel();job.main.post(()->{if(!job.closed){job.result=null;job.saved=List.of();job.phase=Phase.ERROR;job.message="Sleep history or saved analyses changed. Close and reopen this screen.";job.notifyNow();}});}}
    private static boolean sourceIs(JSONObject source,long record,long clip){return source!=null&&source.optLong("record")==record&&(clip<=0||source.optLong("clip")==clip);}
    static void invalidateSource(long record,long clip){for(RecordedRecognitionJob job:JOBS){RecordedRecognitionInput input=job.input;RecordedRecognitionStore.Entry result=job.result;if(job.record==record||input!=null&&sourceIs(input.source,record,clip)||result!=null&&sourceIs(result.source,record,clip)){job.invalidated=true;job.cancel();job.main.post(()->{if(!job.closed){job.result=null;job.saved=List.of();job.phase=Phase.ERROR;job.message="The source recording was removed or changed. Close and reopen this screen.";job.notifyNow();}});}}}
    @Override public void close(){if(closed)return;cancel();closed=true;observer=null;JOBS.remove(this);worker.shutdown();}
}
